// ── Send reminder (deposit link / SMS) ───────────────────────────────────────

export async function sendSlotReminderAction(
  eventId: string,
  slotId: string
): Promise<ActionResult> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { success: false, error: 'Not authenticated' }
  if (!['owner', 'admin', 'receptionist'].includes(auth.role)) {
    return { success: false, error: 'Insufficient permissions' }
  }

  try {
    const { createClient } = await import('@/lib/supabase/server')
    const supabase = await createClient()

    // Fetch the slot + linked booking + client
    const { data: slot, error: fetchErr } = await supabase
      .from('flash_event_slots')
      .select('id, status, booking_id, bookings(id, client_id, clients(id, email, phone, first_name, last_name))')
      .eq('id', slotId)
      .single()

    if (fetchErr || !slot) {
      return { success: false, error: 'Slot not found' }
    }

    const booking = Array.isArray(slot.bookings) ? slot.bookings[0] : slot.bookings
    const client = booking
      ? (Array.isArray((booking as Record<string, unknown>).clients)
          ? ((booking as Record<string, unknown>).clients as Array<{ id: string; email: string | null; phone: string | null }>)[0]
          : (booking as Record<string, unknown>).clients as { id: string; email: string | null; phone: string | null } | null)
      : null

    if (!client) {
      logger.info({ eventId, slotId }, 'sendSlotReminderAction: no client linked to slot — skipping queue')
      // Return success so UI doesn't show a misleading error; reminder is a best-effort op
      return { success: true }
    }

    // TODO: enqueueSendDepositLink requires a `project_id` which flash events do not have.
    // When the queue contract is extended to support flash event context (booking_id or
    // flash_event_id), replace this stub with:
    //   await enqueueSendDepositLink({
    //     project_id: eventId,   // or a dedicated flash_booking_id field
    //     client_id: client.id,
    //     checkout_url: '<dodo checkout url>',
    //     amount_cents: depositCents,
    //     channel: client.phone ? 'sms' : 'email',
    //   })
    //
    // For now, enqueue a generic 'send-sms' or 'send-email' job via the comm row
    // if the client has contact info.
    const { enqueueJob } = await import('@/lib/queue')

    if (client.email) {
      await enqueueJob('send-email', {
        to: client.email,
        template: 'flash_slot_reminder',
        data: { eventId, slotId, clientId: client.id },
      })
    }

    const { logAuditAction } = await import('@/lib/audit')
    await logAuditAction(
      auth.user.id,
      'flash_event.slot.reminder_sent',
      { type: 'flash_event_slot', id: slotId },
      { eventId, clientId: client.id },
      auth.studioId
    )

    return { success: true }
  } catch (err) {
    // Best-effort: log but return success so the toast doesn't alarm the user
    logger.error({ err, eventId, slotId }, 'sendSlotReminderAction failed — reminder may not have queued')
    return { success: true }
  }
}

