export async function sendSlotReminderAction(
  eventId: string,
  slotId: string
): Promise<ActionResult> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { success: false, error: 'Not authenticated' }
  if (!['owner', 'admin', 'receptionist'].includes(auth.role)) {
    return { success: false, error: 'Insufficient permissions' }
  }

  try {
    const { createClient } = await import('@/lib/supabase/server')
    const supabase = await createClient()

    // Fetch slot + linked booking + client email
    const { data: slotRow, error: fetchErr } = await supabase
      .from('flash_event_slots')
      .select('id, status, booking_id')
      .eq('id', slotId)
      .single()

    if (fetchErr || !slotRow) {
      return { success: false, error: 'Slot not found' }
    }

    let clientEmail: string | null = null
    let clientId: string | null = null

    if (slotRow.booking_id) {
      const { data: bookingRow } = await supabase
        .from('bookings')
        .select('client_id, clients(id, email)')
        .eq('id', slotRow.booking_id)
        .single()

      const rawClient = bookingRow?.clients
      const client = Array.isArray(rawClient) ? rawClient[0] : rawClient
      clientEmail = (client as { email: string | null } | undefined)?.email ?? null
      clientId = (client as { id: string } | undefined)?.id ?? null
    }

    if (!clientEmail) {
      // No contact info — log and return success (best-effort, non-blocking)
      logger.info({ eventId, slotId }, 'sendSlotReminderAction: no client email on slot — skipping queue')
      return { success: true }
    }

    // TODO: enqueueSendDepositLink requires `project_id` (a tattoo project concept).
    // Flash events have no project_id. When the queue contract is extended to support
    // flash_event context (e.g. flash_booking_id), replace the send-email stub below with:
    //   await enqueueSendDepositLink({
    //     project_id: '<flash_booking_id or eventId bridge>',
    //     client_id: clientId,
    //     checkout_url: '<dodo checkout url from booking>',
    //     amount_cents: depositCents,
    //     channel: clientPhone ? 'sms' : 'email',
    //   })
    const { enqueueJob } = await import('@/lib/queue')
    await enqueueJob('send-email', {
      to: clientEmail,
      template: 'flash_slot_reminder',
      data: { eventId, slotId, clientId },
    })

    const { logAuditAction } = await import('@/lib/audit')
    await logAuditAction(
      auth.user.id,
      'flash_event.slot.reminder_sent',
      { type: 'flash_event_slot', id: slotId },
      { eventId, clientId },
      auth.studioId
    )

    return { success: true }
  } catch (err) {
    // Best-effort: log but return success — reminder is non-critical
    logger.error({ err, eventId, slotId }, 'sendSlotReminderAction failed — reminder may not have queued')
    return { success: true }
  }
}

