export async function reopenSlotAction(
  eventId: string,
  slotId: string
): Promise<ActionResult> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { success: false, error: 'Not authenticated' }
  if (!['owner', 'admin', 'receptionist'].includes(auth.role)) {
    return { success: false, error: 'Insufficient permissions' }
  }

  try {
    const { createServiceRoleClient } = await import('@/lib/supabase/server')
    const supabase = createServiceRoleClient()

    // CHECK constraint chk_flash_slot_booked_has_booking allows status='open' with null booking_id.
    const { error } = await supabase
      .from('flash_event_slots')
      .update({
        status: 'open',
        booking_id: null,
        design_id: null,
        walk_in: false,
        no_show_marked_at: null,
        checked_in_at: null,
        grace_expires_at: null,
        updated_at: new Date().toISOString(),
      } as Parameters<ReturnType<typeof supabase.from>['update']>[0])
      .eq('id', slotId)
      .eq('status', 'no_show')

    if (error) {
      logger.error({ error, eventId, slotId }, 'reopenSlotAction update failed')
      return { success: false, error: error.message }
    }

    const { logAuditAction } = await import('@/lib/audit')
    await logAuditAction(
      auth.user.id,
      'flash_event.slot.reopen',
      { type: 'flash_event_slot', id: slotId },
      { eventId },
      auth.studioId
    )

    revalidatePath(`/flash-events/${eventId}`)
    return { success: true }
  } catch (err) {
    logger.error({ err, eventId, slotId }, 'reopenSlotAction failed')
    const message = err instanceof Error ? err.message : 'Failed to reopen slot'
    return { success: false, error: message }
  }
}

// ── Cancel reservation (reserved → open) ─────────────────────────────────────

export async function cancelSlotReservationAction(
  eventId: string,
  slotId: string
): Promise<ActionResult> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { success: false, error: 'Not authenticated' }
  if (!['owner', 'admin', 'receptionist'].includes(auth.role)) {
    return { success: false, error: 'Insufficient permissions' }
  }

  try {
    const { createServiceRoleClient } = await import('@/lib/supabase/server')
    const supabase = createServiceRoleClient()

    const { error } = await supabase
      .from('flash_event_slots')
      .update({
        status: 'open',
        booking_id: null,
        reserved_until: null,
        updated_at: new Date().toISOString(),
      } as Parameters<ReturnType<typeof supabase.from>['update']>[0])
      .eq('id', slotId)
      .eq('status', 'reserved')

    if (error) {
      logger.error({ error, eventId, slotId }, 'cancelSlotReservationAction update failed')
      return { success: false, error: error.message }
    }

    const { logAuditAction } = await import('@/lib/audit')
    await logAuditAction(
      auth.user.id,
      'flash_event.slot.reservation_cancelled',
      { type: 'flash_event_slot', id: slotId },
      { eventId },
      auth.studioId
    )

    revalidatePath(`/flash-events/${eventId}`)
    return { success: true }
  } catch (err) {
    logger.error({ err, eventId, slotId }, 'cancelSlotReservationAction failed')
    const message = err instanceof Error ? err.message : 'Failed to cancel reservation'
    return { success: false, error: message }
  }
}

