/**
 * Flash event no-show sweep — utility function.
 *
 * Finds flash_event_slots where:
 *   - status = 'booked'
 *   - grace_expires_at < now()
 *   - checked_in_at IS NULL
 *
 * For each matched slot, calls RPC mark_flash_slot_no_show(p_slot_id).
 *
 * Used by workers/cron/flash-no-show-sweep.ts (runs every 5 min).
 * Uses the service-role client (bypasses RLS — no user session in cron context).
 */
import 'server-only'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'

interface ExpiredSlotRow {
  id: string
  booking_id: string | null
}

/**
 * Sweep expired flash slots and mark them as no-show.
 * Returns the count of slots swept.
 */
export async function sweepFlashNoShows(): Promise<{ swept: number; failed: number }> {
  const runLog = logger.child({ sweep: 'flash-no-show-sweep' })
  runLog.info('flash-no-show-sweep: scanning for expired slots')

  const supabase = createServiceRoleClient()

  // ── 1. Find expired booked slots ──────────────────────────────────────────
  const { data: expiredSlots, error: fetchErr } = await supabase
    .from('flash_event_slots')
    .select('id, booking_id')
    .eq('status', 'booked')
    .lt('grace_expires_at', new Date().toISOString())
    .is('checked_in_at', null)

  if (fetchErr) {
    runLog.error({ err: fetchErr }, 'flash-no-show-sweep: failed to query expired slots')
    return { swept: 0, failed: 0 }
  }

  const slots = (expiredSlots ?? []) as ExpiredSlotRow[]

  if (slots.length === 0) {
    runLog.info('flash-no-show-sweep: no expired slots found')
    return { swept: 0, failed: 0 }
  }

  runLog.info({ count: slots.length }, 'flash-no-show-sweep: found expired slots')

  // ── 2. Mark each as no-show via RPC ─────────────────────────────────────
  const results = await Promise.allSettled(
    slots.map(async (slot) => {
      const { data, error } = await (supabase.rpc as unknown as (
        fn: 'mark_flash_slot_no_show',
        args: { p_slot_id: string }
      ) => Promise<{ data: boolean | null; error: { message: string } | null }>)(
        'mark_flash_slot_no_show',
        { p_slot_id: slot.id }
      )

      if (error) {
        throw new Error(`RPC failed for slot ${slot.id}: ${error.message}`)
      }

      if (!data) {
        // RPC returned false — slot already transitioned (race condition — safe to skip)
        runLog.warn({ slotId: slot.id }, 'flash-no-show-sweep: RPC returned false for slot (race or already changed)')
      }

      return slot.id
    })
  )

  let swept = 0
  let failed = 0

  results.forEach((result, idx) => {
    if (result.status === 'fulfilled') {
      swept++
    } else {
      failed++
      runLog.error({ err: result.reason, slotId: slots[idx]?.id }, 'flash-no-show-sweep: failed to mark slot')
    }
  })

  runLog.info({ swept, failed }, 'flash-no-show-sweep: run complete')
  return { swept, failed }
}

/**
 * Flash event no-show sweep — cron job.
 *
 * Runs every 5 minutes.
 * Finds flash_event_slots where:
 *   - status = 'booked'
 *   - grace_expires_at < now()
 *   - checked_in_at IS NULL
 *
 * For each matched slot, calls RPC mark_flash_slot_no_show(p_slot_id).
 *
 * Uses service-role client (bypasses RLS — no user session in cron context).
 * Index idx_flash_event_slots_grace (added in migration 20260428100000) makes
 * this query fast even at high slot volume.
 */
import { supabase } from '../lib/supabase'
import { logger } from '../lib/logger'

interface ExpiredSlotRow {
  id: string
  booking_id: string | null
}

export async function runFlashNoShowSweep(): Promise<void> {
  const runLog = logger.child({ cron: 'flash-no-show-sweep' })
  runLog.info('flash-no-show-sweep: scanning for expired grace windows')

  try {
    // ── 1. Find expired booked slots ────────────────────────────────────────
    const { data: expiredSlots, error: fetchErr } = await supabase
      .from('flash_event_slots')
      .select('id, booking_id')
      .eq('status', 'booked')
      .lt('grace_expires_at', new Date().toISOString())
      .is('checked_in_at', null)

    if (fetchErr) {
      runLog.error({ err: fetchErr }, 'flash-no-show-sweep: failed to query expired slots')
      return
    }

    const slots = (expiredSlots ?? []) as ExpiredSlotRow[]

    if (slots.length === 0) {
      runLog.info('flash-no-show-sweep: no expired slots')
      return
    }

    runLog.info({ count: slots.length }, 'flash-no-show-sweep: found expired slots')

    // ── 2. Mark each as no-show via RPC ─────────────────────────────────────
    // RPC is SECURITY DEFINER so service-role is sufficient here.
    const results = await Promise.allSettled(
      slots.map(async (slot) => {
        const { data, error } = await (supabase.rpc as unknown as (
          fn: 'mark_flash_slot_no_show',
          args: { p_slot_id: string }
        ) => Promise<{ data: boolean | null; error: { message: string } | null }>)(
          'mark_flash_slot_no_show',
          { p_slot_id: slot.id }
        )

        if (error) {
          throw new Error(`RPC failed for slot ${slot.id}: ${error.message}`)
        }

        if (!data) {
          // RPC returned false — slot already transitioned (race condition — safe to skip)
          runLog.warn({ slotId: slot.id }, 'flash-no-show-sweep: RPC returned false (slot already changed)')
        }

        return slot.id
      })
    )

    let swept = 0
    let failed = 0

    results.forEach((result, idx) => {
      if (result.status === 'fulfilled') {
        swept++
      } else {
        failed++
        runLog.error(
          { err: result.reason, slotId: slots[idx]?.id },
          'flash-no-show-sweep: failed to mark slot no-show'
        )
      }
    })

    runLog.info({ swept, failed }, 'flash-no-show-sweep: run complete')
  } catch (err: unknown) {
    runLog.error({ err }, 'flash-no-show-sweep: unexpected error in cron run')
  }
}

